"""Inputs and outputs of the workflows and of run_job.

These dataclasses are the contract with whoever starts the workflows
(be_service, the temporal CLI): they travel as JSON, so field names are the
API. New fields only with defaults, so running workflows keep decoding.
"""

from dataclasses import dataclass, field


@dataclass
class TrainInput:
    # Generated by be_service per button press; empty means "make one up".
    run_id: str = ""
    epochs: int = 3
    pool: str = "gpu"
    # A new model becomes champion only if it beats the current one by more.
    min_improvement: float = 0.0


@dataclass
class TrainResult:
    run_id: str
    version: str
    accuracy: float
    train_samples: int
    promoted: bool
    # Champion before this run: version and accuracy, None on the first run.
    previous_champion: dict | None


@dataclass
class RunInput:
    run_id: str = ""
    model: str = "champion"
    pool: str = "cpu"


@dataclass
class RunResult:
    run_id: str
    model_version: str
    accuracy: float
    rows: int


@dataclass
class ReportInput:
    # The prediction run to report on (be_service passes the latest one).
    prediction_run_id: str
    run_id: str = ""


@dataclass
class ReportResult:
    run_id: str
    prediction_run_id: str
    model_version: str
    total: int
    # One entry per digit: {"digit", "recognized", "actual"}.
    digits: list[dict]
    most_over: dict
    most_under: dict


@dataclass
class JobRequest:
    """One pipeline step as a Kubernetes Job running the mle-models image."""

    step: str  # train | predict | report | promote
    run_id: str
    args: list[str] = field(default_factory=list)
    pool: str = "cpu"  # node pool from the cluster contract: cpu | gpu
    cpu: str = "1"
    memory: str = "512Mi"
    # Kubernetes kills the Job after this; the activity timeout is a bit longer.
    deadline_seconds: int = 600
